SET @task_id=208;
SELECT 'ACCOUNT' section,a.id,a.protocol_id,s.account_state,s.login_state,s.risk_status,s.mute_status,s.restriction_reason_code,s.block_error_code,LEFT(s.block_reason,160) block_reason,FROM_UNIXTIME(s.pulling_restriction_until/1000) pulling_restriction_until,FROM_UNIXTIME(s.cooldown_until/1000) cooldown_until,FROM_UNIXTIME(s.updated_at/1000) updated_at FROM account a JOIN account_state s ON s.account_id=a.id WHERE a.id IN (SELECT account_id FROM pull_task_group_account WHERE task_id=@task_id AND role_type IN (1,2)) ORDER BY a.id;
SELECT 'ATTEMPT' section,group_execution_id,puller_group_account_id,lifecycle_status,protocol_outcome,execution_state,reason_code,COUNT(*) n,MIN(attempt_no) min_attempt_no,MAX(attempt_no) max_attempt_no,LEFT(MAX(reason_message),200) example_reason,FROM_UNIXTIME(MAX(result_at)/1000) last_result FROM pull_task_pull_call_member_attempt WHERE task_id=@task_id GROUP BY group_execution_id,puller_group_account_id,lifecycle_status,protocol_outcome,execution_state,reason_code;
SELECT 'BINDING_MISMATCH' section,c.id call_id,c.group_execution_id,a.id attempt_id,a.participant_ref_id member_id,a.lifecycle_status,a.reason_code,a.protocol_outcome,FROM_UNIXTIME(a.created_at/1000) attempt_created,m.pull_call_id actual_call_id,m.active_pull_attempt_id,m.pull_status,m.pull_reason_code,FROM_UNIXTIME(m.updated_at/1000) member_updated FROM pull_task_pull_call c JOIN pull_task_pull_call_member_attempt a ON a.pull_call_id=c.id JOIN pull_task_material_member m ON m.id=a.participant_ref_id WHERE c.task_id=@task_id AND c.call_status=1 AND a.participant_type=1 AND (m.pull_call_id IS NULL OR m.pull_call_id<>c.id) ORDER BY c.group_execution_id,c.id;
SELECT 'CALL_8916_8934_ATTEMPTS' section,a.id,a.pull_call_id,a.participant_ref_id,a.lifecycle_status,a.reason_code,a.protocol_outcome,a.active_slot,FROM_UNIXTIME(a.updated_at/1000) attempt_updated,m.pull_call_id actual_call_id,m.pull_status,m.pull_reason_code FROM pull_task_pull_call_member_attempt a JOIN pull_task_material_member m ON m.id=a.participant_ref_id WHERE a.pull_call_id IN (8916,8934) ORDER BY a.pull_call_id,a.id;
SELECT 'MANAGER_ACTION' section,id,group_execution_id,action_type,action_status,attempt_no,reason_code,reason_message,FROM_UNIXTIME(created_at/1000) created_at,FROM_UNIXTIME(submitted_at/1000) submitted_at,FROM_UNIXTIME(result_at/1000) result_at FROM pull_task_account_action WHERE task_id=@task_id AND group_execution_id IN (503,505,506);
SELECT 'RUNTIME_SNAPSHOT' section,NOW(3) observed_at,e.id,e.source_file_name,e.execution_status,e.reason_code,e.active_pull_wave_id,e.active_puller_group_account_id,SUM(m.pull_status=2) success,SUM(m.pull_status=0) pending,SUM(m.pull_status=1) submitting,SUM(m.pull_status=3) failed,SUM(m.pull_status=4) unknown,FROM_UNIXTIME(e.last_business_executed_at/1000) last_business_at,FROM_UNIXTIME(MAX(m.pull_result_at)/1000) last_member_result FROM pull_task_group_execution e JOIN pull_task_material_member m ON m.group_execution_id=e.id WHERE e.task_id=@task_id GROUP BY e.id ORDER BY e.seq,e.attempt_no;
